import { assertCompiledPackageManifest, bindingArtifactDigest } from './manifest.js';
function jsString(value) {
    return JSON.stringify(value);
}
export function emitTargetCompiledPackageModule(input) {
    assertCompiledPackageManifest(input.manifest);
    const isSuccessor = input.manifest.formatVersion === '0.3'
        && input.manifest.runtimeContractMajor === 2
        && input.manifest.executionEngineMajor === 3;
    if (!isSuccessor && input.domainData !== undefined) {
        throw new Error('domainData values may only be emitted for a successor 0.3/2/3 package');
    }
    if (isSuccessor && input.domainData === undefined) {
        throw new Error('successor 0.3/2/3 package emission requires its bundled domainData values');
    }
    if (isSuccessor && input.domainData !== undefined) {
        // Emitted bundled values must be exactly the manifest's declared Domain
        // Data entries: the generated module cannot smuggle keys whose descriptor
        // digests never entered the package identity.
        const declared = new Set((input.manifest.domainData ?? []).map((descriptor) => descriptor.key));
        const bundled = Object.keys(input.domainData);
        if (bundled.length !== declared.size || bundled.some((key) => !declared.has(key))) {
            throw new Error('emitted domainData values do not match the manifest Domain Data descriptors');
        }
    }
    const bindingIds = Object.keys(input.manifest.bindingDigests).sort();
    const imports = [];
    const assignments = [];
    bindingIds.forEach((bindingId, index) => {
        const reference = input.bindingModules[bindingId];
        if (!reference)
            throw new Error(`no generated module reference supplied for binding '${bindingId}'`);
        if (!reference.moduleSpecifier || /[\r\n\0]/u.test(reference.moduleSpecifier) || /^[a-z][a-z0-9+.-]*:\/\//iu.test(reference.moduleSpecifier))
            throw new Error(`invalid module specifier for binding '${bindingId}'`);
        if (typeof reference.content !== 'string' || reference.content.length === 0)
            throw new Error(`no immutable content identity supplied for binding '${bindingId}'`);
        const contentDigest = bindingArtifactDigest(bindingId, reference.content);
        const manifestDigest = input.manifest.bindingDigests[bindingId];
        if (manifestDigest !== contentDigest) {
            throw new Error(`binding '${bindingId}' module content digest '${contentDigest}' does not match manifest bindingDigests['${bindingId}'] '${manifestDigest ?? '<missing>'}'`);
        }
        const local = `__binding_${index}`;
        if (reference.exportName) {
            if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/u.test(reference.exportName))
                throw new Error(`invalid export name '${reference.exportName}' for binding '${bindingId}'`);
            imports.push(`import { ${reference.exportName} as ${local} } from ${jsString(reference.moduleSpecifier)};`);
        }
        else {
            imports.push(`import ${local} from ${jsString(reference.moduleSpecifier)};`);
        }
        assignments.push(`${jsString(bindingId)}: ${local}`);
    });
    const manifestJson = JSON.stringify(input.manifest, null, 2);
    const domainDataJson = input.domainData === undefined ? undefined : JSON.stringify(input.domainData, null, 2);
    return [
        '// Generated by @kaicreator/domain-harness-compiler. Do not edit.',
        ...imports,
        '',
        `export const manifest = Object.freeze(${manifestJson});`,
        `export const bindings = Object.freeze({${assignments.join(', ')}});`,
        ...(domainDataJson === undefined
            ? ['const compiledPackage = Object.freeze({ manifest, bindings });']
            : [
                `export const domainData = Object.freeze(${domainDataJson});`,
                'const compiledPackage = Object.freeze({ manifest, bindings, domainData });',
            ]),
        'export default compiledPackage;',
        '',
    ].join('\n');
}
